package modelgen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"

	"github.com/monstercameron/hcm-next/internal/intent/model"
)

// GeneratedHeader is the exact first line of every file this package writes,
// so a drift check or a human reviewer can find generated code with one
// literal grep.
const GeneratedHeader = "// Code generated by tools/gen/modelgen. DO NOT EDIT."

// OutputFile is the single generated file [Render] produces under
// gen/go/hcmnext/model. One file (rather than the types/registry split a
// larger generator might use) keeps [Render] a single deterministic pass
// with one, easy-to-audit import block.
const OutputFile = "model_generated.go"

// Render turns ms into formatted Go source for [OutputFile]. It is pure: the
// same ModelSet always renders to the same bytes, because every loop below
// walks a slice [Build] already sorted, never a map.
func Render(ms *ModelSet) (map[string][]byte, error) {
	if ms == nil {
		return nil, fmt.Errorf("modelgen: Render: nil model set")
	}

	var b bytes.Buffer
	b.WriteString(GeneratedHeader + "\n")
	fmt.Fprintf(&b, "// Generated from the internal/intent/model registry, source digest %s.\n\n", ms.SourceDigest)
	b.WriteString("package model\n\n")

	renderImports(&b, ms)

	fmt.Fprintf(&b, "// SourceRegistryDigest is %s\n", "the [github.com/monstercameron/hcm-next/internal/intent/model.Registry.Digest] this package was generated from.")
	b.WriteString("// New's caller can compare it against a freshly compiled catalog to detect drift at runtime, not only at generation time.\n")
	fmt.Fprintf(&b, "const SourceRegistryDigest = %q\n\n", ms.SourceDigest)

	for _, e := range ms.Entities {
		renderEntity(&b, e)
	}

	renderRegistry(&b, ms)

	formatted, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("modelgen: format generated Go: %w\n---\n%s", err, b.String())
	}
	return map[string][]byte{OutputFile: formatted}, nil
}

// renderImports writes the import block. "fmt" is always needed (every
// Validate method returns a *fmt.Errorf*); values/lifecycle are added only
// when some field actually uses them, so the generated file never imports a
// package it does not reference.
func renderImports(b *bytes.Buffer, ms *ModelSet) {
	need := map[string]bool{}
	for _, e := range ms.Entities {
		for _, f := range e.Fields {
			for _, imp := range f.Type.imports {
				need[imp] = true
			}
		}
	}
	imports := make([]string, 0, len(need)+1)
	for imp := range need {
		imports = append(imports, imp)
	}
	sort.Strings(imports)

	b.WriteString("import (\n\t\"crypto/sha256\"\n\t\"encoding/hex\"\n\t\"fmt\"\n")
	if len(imports) > 0 {
		b.WriteString("\n")
		for _, imp := range imports {
			fmt.Fprintf(b, "\t%q\n", imp)
		}
	}
	b.WriteString(")\n\n")
}

// renderEntity writes one entity's struct type and Validate method.
func renderEntity(b *bytes.Buffer, e EntityModel) {
	fmt.Fprintf(b, "// %s is the generated typed model for %s, one field per registered property.\n",
		e.TypeName, e.Entity.Ref)
	fmt.Fprintf(b, "type %s struct {\n", e.TypeName)
	for _, f := range e.Fields {
		fmt.Fprintf(b, "\t// %s is %s (%s).\n", f.FieldName, f.Property.Ref, f.Property.SchemaPath)
		fmt.Fprintf(b, "\t%s %s\n", f.FieldName, f.Type.goType)
	}
	b.WriteString("}\n\n")

	fmt.Fprintf(b, "// Validate enforces %s's REQUIRED properties: presence for a plain Go type,\n", e.TypeName)
	b.WriteString("// and the declared internal/kernel/values or internal/intent/lifecycle\n")
	b.WriteString("// invariant for a typed one. An OPTIONAL or CONDITIONAL property is never\n")
	b.WriteString("// checked here.\n")
	fmt.Fprintf(b, "func (v %s) Validate() error {\n", e.TypeName)
	for _, f := range e.Fields {
		if f.Property.Presence != model.PresenceRequired {
			continue
		}
		renderRequiredCheck(b, e.TypeName, f)
	}
	b.WriteString("\treturn nil\n}\n\n")
}

// renderRequiredCheck emits the one `if` statement enforcing field f's
// presence, dispatched on its resolved [fieldKind]. Every case in
// [typeTable] is handled explicitly — there is no default branch — so a
// future kind added to the table without a case here fails to compile
// instead of silently validating nothing.
func renderRequiredCheck(b *bytes.Buffer, typeName string, f FieldModel) {
	expr := "v." + f.FieldName
	label := fmt.Sprintf("%s.%s (%s)", typeName, f.FieldName, f.Property.Ref)
	switch f.Type.kind {
	case kindString, kindStateID:
		fmt.Fprintf(b, "\tif %s == \"\" {\n\t\treturn fmt.Errorf(\"model: %s is required\")\n\t}\n", expr, label)
	case kindUint32:
		fmt.Fprintf(b, "\tif %s == 0 {\n\t\treturn fmt.Errorf(\"model: %s is required\")\n\t}\n", expr, label)
	case kindStringSlice:
		fmt.Fprintf(b, "\tif len(%s) == 0 {\n\t\treturn fmt.Errorf(\"model: %s is required\")\n\t}\n", expr, label)
	case kindDecimal, kindInterval, kindInstant, kindDimensions:
		fmt.Fprintf(b, "\tif err := %s.Validate(); err != nil {\n\t\treturn fmt.Errorf(\"model: %s: %%w\", err)\n\t}\n", expr, label)
	case kindKnownAt, kindRecordedAt:
		fmt.Fprintf(b, "\tif err := %s.Instant().Validate(); err != nil {\n\t\treturn fmt.Errorf(\"model: %s: %%w\", err)\n\t}\n", expr, label)
	default:
		// Unreachable: resolveGoType only ever returns a kind declared in
		// typeTable, and every one of those kinds is a case above. A panic
		// here means typeTable grew a kind this switch does not know about
		// yet, which is a generator bug to fix, not a value to guess at.
		panic(fmt.Sprintf("modelgen: renderRequiredCheck: unhandled field kind %d for %s", f.Type.kind, label))
	}
}

// renderRegistry writes the plain-string metadata descriptors (EntityMeta,
// PropertyMeta, RelationshipMeta), their compiled-in tables, and the
// generated Registry type.
//
// Descriptors are plain strings, not the internal/intent/model enum types,
// deliberately: a Binding in
// [github.com/monstercameron/hcm-next/internal/intent/definitions] already
// names an entity or property by bare string (e.g. "Person",
// "employment.status"), so a caller can compare a binding against this
// registry with no conversion step. It is also the descriptor shape
// [github.com/monstercameron/hcm-next/tools/gen/schemaflux/modelgen] already
// established for a generated registry in this repository.
func renderRegistry(b *bytes.Buffer, ms *ModelSet) {
	b.WriteString("// EntityMeta is one generated entity descriptor.\n")
	b.WriteString("type EntityMeta struct {\n\tName string\n\tVersion int\n\tKey string\n\tOwnerDomain string\n\tClass string\n\tLifecycleAssignment string\n\tTenantScoped bool\n\tStatus string\n}\n\n")
	b.WriteString("// Ref renders the canonical \"Name/vN\" form.\n")
	b.WriteString("func (e EntityMeta) Ref() string { return fmt.Sprintf(\"%s/v%d\", e.Name, e.Version) }\n\n")

	b.WriteString("// PropertyMeta is one generated property descriptor. Ref is the exact\n")
	b.WriteString("// \"entity_key.path\" string a Binding's ReadProperties/WriteProperties carries.\n")
	b.WriteString("type PropertyMeta struct {\n\tRef string\n\tEntity string\n\tGoType string\n\tSchemaPath string\n\tPresence string\n\tClassification string\n\tTemporal string\n\tAuthorityRef string\n\tCorrection string\n\tRetentionClassRef string\n\tStatus string\n\t// Immutable marks a property no drafted definition may write: an\n\t// IMMUTABLE, IMMUTABLE_NO_CORRECTION property on a non-EVIDENCE entity.\n\t// See modelgen's isImmutableWrite for the exact rule.\n\tImmutable bool\n}\n\n")

	b.WriteString("// RelationshipMeta is one generated relationship descriptor.\n")
	b.WriteString("type RelationshipMeta struct {\n\tName string\n\tVersion int\n\tSourceEntity string\n\tTargetEntity string\n\tCardinality string\n\tExclusive bool\n\tAllowCycles bool\n\tTenantScoped bool\n}\n\n")

	b.WriteString("var entityMetas = []EntityMeta{\n")
	for _, e := range ms.Entities {
		fmt.Fprintf(b, "\t{Name: %q, Version: %d, Key: %q, OwnerDomain: %q, Class: %q, LifecycleAssignment: %q, TenantScoped: %t, Status: %q},\n",
			e.Entity.Ref.Name, e.Entity.Ref.Version, e.Entity.Key, e.Entity.OwnerDomain,
			string(e.Entity.Class), e.Entity.LifecycleAssignment, e.Entity.TenantScoped, string(e.Entity.Status))
	}
	b.WriteString("}\n\n")

	b.WriteString("var propertyMetas = []PropertyMeta{\n")
	for _, e := range ms.Entities {
		for _, f := range e.Fields {
			p := f.Property
			fmt.Fprintf(b,
				"\t{Ref: %q, Entity: %q, GoType: %q, SchemaPath: %q, Presence: %q, Classification: %q, Temporal: %q, AuthorityRef: %q, Correction: %q, RetentionClassRef: %q, Status: %q, Immutable: %t},\n",
				string(p.Ref), p.Entity.Name, p.GoType, p.SchemaPath, string(p.Presence), string(p.Classification),
				string(p.Temporal), p.AuthorityRef, string(p.Correction), p.RetentionClassRef, string(p.Status), f.Immutable)
		}
	}
	b.WriteString("}\n\n")

	b.WriteString("var relationshipMetas = []RelationshipMeta{\n")
	for _, r := range ms.Relationships {
		d := r.Def
		fmt.Fprintf(b, "\t{Name: %q, Version: %d, SourceEntity: %q, TargetEntity: %q, Cardinality: %q, Exclusive: %t, AllowCycles: %t, TenantScoped: %t},\n",
			d.Ref.Name, d.Ref.Version, d.SourceEntity.Name, d.TargetEntity.Name, string(d.Cardinality), d.Exclusive, d.AllowCycles, d.TenantScoped)
	}
	b.WriteString("}\n\n")

	b.WriteString(`// Registry publishes the generated entity, property and relationship
// metadata this package compiles. It is immutable once constructed by [New]:
// like internal/intent/model.Registry, there is no Add, Remove or setter.
type Registry struct {
	entities      []EntityMeta
	entityByName  map[string]EntityMeta
	properties    []PropertyMeta
	propertyByRef map[string]PropertyMeta
	relationships []RelationshipMeta
}

// New compiles the generated tables into a Registry. The tables are baked in
// at generation time and already validated ([Build] never emits an
// unresolved reference or an unrecognized Go type), so New performs no
// validation of its own; it only indexes.
func New() *Registry {
	r := &Registry{
		entities:      entityMetas,
		entityByName:  make(map[string]EntityMeta, len(entityMetas)),
		properties:    propertyMetas,
		propertyByRef: make(map[string]PropertyMeta, len(propertyMetas)),
		relationships: relationshipMetas,
	}
	for _, e := range entityMetas {
		// Later (higher-version) entries win: entityMetas is generated in
		// sorted (Name, Version) order, so a later loop iteration is always
		// the newer material version of that name.
		r.entityByName[e.Name] = e
	}
	for _, p := range propertyMetas {
		r.propertyByRef[p.Ref] = p
	}
	return r
}

// Entities returns every generated entity descriptor, in generation order.
func (r *Registry) Entities() []EntityMeta { return append([]EntityMeta(nil), r.entities...) }

// EntityByName resolves an entity by its bare PascalCase name (e.g.
// "Person"), the form a Binding's AggregateRoots carries. It resolves to the
// highest published material version of that name.
func (r *Registry) EntityByName(name string) (EntityMeta, bool) {
	e, ok := r.entityByName[name]
	return e, ok
}

// Properties returns every generated property descriptor, in generation
// order (grouped by owning entity, then by PropertyRef within the entity).
func (r *Registry) Properties() []PropertyMeta { return append([]PropertyMeta(nil), r.properties...) }

// Property resolves a property by its exact "entity_key.path" reference, the
// form a Binding's ReadProperties/WriteProperties carries.
func (r *Registry) Property(ref string) (PropertyMeta, bool) {
	p, ok := r.propertyByRef[ref]
	return p, ok
}

// Relationships returns every generated relationship descriptor.
func (r *Registry) Relationships() []RelationshipMeta {
	return append([]RelationshipMeta(nil), r.relationships...)
}

`)
	b.WriteString("// Digest computes a stable sha256 digest over every compiled descriptor plus\n")
	b.WriteString("// SourceRegistryDigest, the same canonical-parts convention\n")
	b.WriteString("// internal/intent/model.Registry.Digest and tools/gen/storagemanifest use: two\n")
	b.WriteString("// Registrys built from identical generated tables always agree.\n")
	b.WriteString(`func (r *Registry) Digest() string {
	h := sha256.New()
	w := func(parts ...string) {
		for _, p := range parts {
			h.Write([]byte(p))
			h.Write([]byte{0})
		}
	}
	w("SOURCE", SourceRegistryDigest)
	for _, e := range r.entities {
		w("ENTITY", e.Name, fmt.Sprint(e.Version), e.Key, e.OwnerDomain, e.Class, e.LifecycleAssignment, fmt.Sprint(e.TenantScoped), e.Status)
	}
	for _, p := range r.properties {
		w("PROPERTY", p.Ref, p.Entity, p.GoType, p.SchemaPath, p.Presence, p.Classification, p.Temporal, p.AuthorityRef, p.Correction, p.RetentionClassRef, p.Status, fmt.Sprint(p.Immutable))
	}
	for _, rel := range r.relationships {
		w("RELATIONSHIP", rel.Name, fmt.Sprint(rel.Version), rel.SourceEntity, rel.TargetEntity, rel.Cardinality, fmt.Sprint(rel.Exclusive), fmt.Sprint(rel.AllowCycles), fmt.Sprint(rel.TenantScoped))
	}
	return "sha256:" + hex.EncodeToString(h.Sum(nil))
}
`)
}
